ue)||0,rate=Number(row.querySelector('.tax-rate').value)||0,discount=Number(row.querySelector('.line-discount').value)||0,type=row.querySelector('.line-discount-type').value;let line=qty*price;line-=type==='percent'?line*discount/100:discount;subtotal+=line;tax+=line*rate/100});const discount=Number(document.getElementById('discount-value').value)||0;const discountType=document.getElementById('discount-type').value;const invoiceDiscount=discountType==='percent'?subtotal*discount/100:discount;const taxable=subtotal-invoiceDiscount;const invoiceTax=tax||taxable*(Number(document.getElementById('invoice-tax').value)||0)/100;document.getElementById('preview-subtotal').textContent=subtotal.toFixed(2);document.getElementById('preview-discount').textContent=invoiceDiscount.toFixed(2);document.getElementById('preview-tax').textContent=invoiceTax.toFixed(2);document.getElementById('preview-total').textContent=(taxable+invoiceTax).toFixed(2)}function bind(row){row.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',updatePreview));row.querySelector('.remove-line').addEventListener('click',()=>{if(items.children.length>1){row.remove();updatePreview()}})}items.querySelectorAll('.item-row').forEach(bind);document.getElementById('add-line').addEventListener('click',()=>{const row=items.querySelector('.item-row').cloneNode(true);row.querySelectorAll('input').forEach(input=>{input.name=input.name.replace(/items\[\d+\]/,`items[${itemIndex}]`);input.value=input.classList.contains('tax-rate')||input.classList.contains('line-discount')?'0':''});items.appendChild(row);bind(row);itemIndex++;updatePreview()});document.querySelectorAll('#discount-value,#discount-type,#invoice-tax').forEach(el=>el.addEventListener('input',updatePreview));updatePreview();</script>@endsection
